schema.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/conversion-tracking.json",
  "title": "Conversion Tracking config",
  "type": "object",
  "required": ["site_domain", "destinations", "registry", "consent", "server_side", "events", "qa"],
  "additionalProperties": false,
  "definitions": {
    "host": {"type": "string", "pattern": "^[a-z0-9.-]+\\.[a-z]{2,}$"},
    "destination": {"type": "string", "enum": ["ga4", "google_ads", "meta", "plausible"]},
    "snake40": {"type": "string", "pattern": "^[a-z][a-z0-9_]{0,39}$", "not": {"pattern": "^(google_|ga_|firebase_|_)"}},
    "consent_value": {"type": "string", "enum": ["denied", "granted"]}
  },
  "properties": {
    "__faion_header__": {"type": ["object", "string"]},
    "site_domain": {"$ref": "#/definitions/host"},
    "destinations": {"type": "array", "minItems": 1, "uniqueItems": true, "items": {"$ref": "#/definitions/destination"}},
    "registry": {
      "type": "object",
      "required": ["file", "ci_validator", "enforced_in_ci"],
      "additionalProperties": false,
      "properties": {"file": {"const": "events.yml"}, "ci_validator": {"const": "validate-events.py"}, "enforced_in_ci": {"const": true}}
    },
    "consent": {
      "type": "object",
      "required": ["mode", "defaults_before_config", "signals", "regional_defaults", "server_honours_consent"],
      "additionalProperties": false,
      "properties": {
        "mode": {"const": "v2"},
        "defaults_before_config": {"const": true},
        "signals": {
          "type": "array",
          "minItems": 4,
          "items": {"type": "string", "enum": ["ad_storage", "analytics_storage", "ad_user_data", "ad_personalization"]},
          "allOf": [{"contains": {"const": "ad_storage"}}, {"contains": {"const": "analytics_storage"}}, {"contains": {"const": "ad_user_data"}}, {"contains": {"const": "ad_personalization"}}]
        },
        "regional_defaults": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "object",
            "required": ["region", "ad_storage", "analytics_storage", "ad_user_data", "ad_personalization"],
            "additionalProperties": false,
            "properties": {
              "region": {"type": "string", "pattern": "^[A-Z]{2}(-[A-Z0-9]{1,3})?$|^default$"},
              "ad_storage": {"$ref": "#/definitions/consent_value"},
              "analytics_storage": {"$ref": "#/definitions/consent_value"},
              "ad_user_data": {"$ref": "#/definitions/consent_value"},
              "ad_personalization": {"$ref": "#/definitions/consent_value"}
            }
          }
        },
        "server_honours_consent": {"const": true}
      }
    },
    "server_side": {
      "type": "object",
      "required": ["enabled"],
      "properties": {"enabled": {"type": "boolean"}},
      "if": {"properties": {"enabled": {"const": true}}},
      "then": {
        "required": ["endpoint", "cookies_http_only", "forwards", "client_id_source", "fresh_ids_generated"],
        "additionalProperties": false,
        "properties": {
          "enabled": {"const": true},
          "endpoint": {"$ref": "#/definitions/host"},
          "cookies_http_only": {"const": true},
          "forwards": {"type": "array", "minItems": 2, "items": {"type": "string", "enum": ["_fbp", "_fbc", "client_id", "session_id"]}, "allOf": [{"contains": {"const": "client_id"}}, {"contains": {"const": "session_id"}}]},
          "client_id_source": {"const": "_ga cookie"},
          "fresh_ids_generated": {"const": false}
        }
      },
      "else": {"additionalProperties": false, "properties": {"enabled": {"const": false}}}
    },
    "events": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["name", "recommended", "parameters", "conversion_role", "monetary", "sent_from"],
        "additionalProperties": false,
        "properties": {
          "name": {"$ref": "#/definitions/snake40"},
          "recommended": {"type": "boolean"},
          "parameters": {
            "type": "array",
            "maxItems": 25,
            "items": {
              "type": "object",
              "required": ["name", "type", "pii"],
              "additionalProperties": false,
              "properties": {
                "name": {"$ref": "#/definitions/snake40"},
                "type": {"type": "string", "enum": ["string", "number", "currency", "boolean", "array"]},
                "max_string_length": {"type": "integer", "minimum": 1, "maximum": 100},
                "pii": {"const": false},
                "hashed": {"type": "boolean"}
              }
            }
          },
          "conversion_role": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "ga4": {"type": ["string", "null"], "enum": ["key_event", "event", null]},
              "google_ads": {"type": ["string", "null"], "enum": ["primary", "secondary", null]},
              "meta": {"type": ["string", "null"], "enum": ["standard", "custom", null]},
              "plausible": {"type": ["string", "null"], "enum": ["goal", "event", null]}
            }
          },
          "monetary": {"type": "boolean"},
          "sent_from": {"type": "array", "minItems": 1, "uniqueItems": true, "items": {"type": "string", "enum": ["browser", "server"]}},
          "dedup": {
            "type": "object",
            "required": ["event_id_field", "shared_across_destinations"],
            "additionalProperties": false,
            "properties": {"event_id_field": {"$ref": "#/definitions/snake40"}, "shared_across_destinations": {"const": true}}
          }
        },
        "allOf": [
          {"if": {"properties": {"monetary": {"const": true}}}, "then": {"required": ["dedup"], "properties": {"dedup": {"properties": {"event_id_field": {"const": "transaction_id"}}}}}},
          {"if": {"properties": {"sent_from": {"minItems": 2}}}, "then": {"required": ["dedup"]}}
        ]
      }
    },
    "qa": {
      "type": "object",
      "required": ["change_ref", "browsers", "adblock_profile", "fixtures"],
      "additionalProperties": false,
      "properties": {
        "change_ref": {"type": "string", "minLength": 3},
        "browsers": {"type": "array", "minItems": 3, "items": {"type": "string", "enum": ["chrome", "safari", "firefox"]}, "allOf": [{"contains": {"const": "chrome"}}, {"contains": {"const": "safari"}}, {"contains": {"const": "firefox"}}]},
        "adblock_profile": {"const": true},
        "fixtures": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "object",
            "required": ["event", "expected_parameters", "example_payload", "results"],
            "additionalProperties": false,
            "properties": {
              "event": {"$ref": "#/definitions/snake40"},
              "expected_parameters": {"type": "array", "items": {"$ref": "#/definitions/snake40"}},
              "example_payload": {"type": "object"},
              "results": {
                "type": "array",
                "minItems": 4,
                "items": {
                  "type": "object",
                  "required": ["browser", "destination", "seen"],
                  "additionalProperties": false,
                  "properties": {
                    "browser": {"type": "string", "enum": ["chrome", "safari", "firefox", "chrome_adblock"]},
                    "destination": {"$ref": "#/definitions/destination"},
                    "seen": {"type": "boolean"}
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}

output-contract.example:
{
  "site_domain": "example.com",
  "destinations": ["ga4", "google_ads", "meta"],
  "registry": {"file": "events.yml", "ci_validator": "validate-events.py", "enforced_in_ci": true},
  "consent": {
    "mode": "v2",
    "defaults_before_config": true,
    "signals": ["ad_storage", "analytics_storage", "ad_user_data", "ad_personalization"],
    "regional_defaults": [
      {"region": "default", "ad_storage": "granted", "analytics_storage": "granted", "ad_user_data": "granted", "ad_personalization": "granted"},
      {"region": "EU", "ad_storage": "denied", "analytics_storage": "denied", "ad_user_data": "denied", "ad_personalization": "denied"},
      {"region": "GB", "ad_storage": "denied", "analytics_storage": "denied", "ad_user_data": "denied", "ad_personalization": "denied"}
    ],
    "server_honours_consent": true
  },
  "server_side": {
    "enabled": true,
    "endpoint": "gtm.example.com",
    "cookies_http_only": true,
    "forwards": ["_fbp", "_fbc", "client_id", "session_id"],
    "client_id_source": "_ga cookie",
    "fresh_ids_generated": false
  },
  "events": [
    {
      "name": "purchase", "recommended": true, "monetary": true, "sent_from": ["browser", "server"],
      "parameters": [
        {"name": "transaction_id", "type": "string", "max_string_length": 64, "pii": false},
        {"name": "value", "type": "number", "pii": false},
        {"name": "currency", "type": "currency", "pii": false},
        {"name": "items", "type": "array", "pii": false},
        {"name": "coupon", "type": "string", "max_string_length": 40, "pii": false}
      ],
      "conversion_role": {"ga4": "key_event", "google_ads": "primary", "meta": "standard"},
      "dedup": {"event_id_field": "transaction_id", "shared_across_destinations": true}
    },
    {
      "name": "sign_up", "recommended": true, "monetary": false, "sent_from": ["browser", "server"],
      "parameters": [
        {"name": "method", "type": "string", "max_string_length": 20, "pii": false},
        {"name": "event_id", "type": "string", "max_string_length": 36, "pii": false},
        {"name": "em", "type": "string", "max_string_length": 64, "pii": false, "hashed": true}
      ],
      "conversion_role": {"ga4": "key_event", "google_ads": "secondary", "meta": "standard"},
      "dedup": {"event_id_field": "event_id", "shared_across_destinations": true}
    },
    {
      "name": "funnel_step", "recommended": false, "monetary": false, "sent_from": ["browser"],
      "parameters": [
        {"name": "funnel_name", "type": "string", "max_string_length": 40, "pii": false},
        {"name": "step_number", "type": "number", "pii": false},
        {"name": "step_name", "type": "string", "max_string_length": 40, "pii": false}
      ],
      "conversion_role": {"ga4": "event", "google_ads": null, "meta": null}
    }
  ],
  "qa": {
    "change_ref": "PR-2214 checkout tracking v3",
    "browsers": ["chrome", "safari", "firefox"],
    "adblock_profile": true,
    "fixtures": [
      {
        "event": "purchase",
        "expected_parameters": ["transaction_id", "value", "currency", "items"],
        "example_payload": {"transaction_id": "ORD-104233", "value": 129.0, "currency": "EUR", "items": [{"item_id": "SKU-88", "quantity": 1}]},
        "results": [
          {"browser": "chrome", "destination": "ga4", "seen": true}, {"browser": "chrome", "destination": "google_ads", "seen": true}, {"browser": "chrome", "destination": "meta", "seen": true},
          {"browser": "safari", "destination": "ga4", "seen": true}, {"browser": "safari", "destination": "google_ads", "seen": true}, {"browser": "safari", "destination": "meta", "seen": true},
          {"browser": "firefox", "destination": "ga4", "seen": true}, {"browser": "firefox", "destination": "google_ads", "seen": true}, {"browser": "firefox", "destination": "meta", "seen": true},
          {"browser": "chrome_adblock", "destination": "ga4", "seen": true}, {"browser": "chrome_adblock", "destination": "google_ads", "seen": true}, {"browser": "chrome_adblock", "destination": "meta", "seen": true}
        ]
      },
      {
        "event": "sign_up",
        "expected_parameters": ["method", "event_id"],
        "example_payload": {"method": "google", "event_id": "5f2a1c9e-3b7d-4e1a-9c6b-2d8e7f1a0b3c", "em": "b4c9a289323b21a01c3e940f150eb9b8c542587f1abfd8f0e1cc1ffc5e475514"},
        "results": [
          {"browser": "chrome", "destination": "ga4", "seen": true}, {"browser": "chrome", "destination": "google_ads", "seen": true}, {"browser": "chrome", "destination": "meta", "seen": true},
          {"browser": "safari", "destination": "ga4", "seen": true}, {"browser": "safari", "destination": "google_ads", "seen": true}, {"browser": "safari", "destination": "meta", "seen": true},
          {"browser": "firefox", "destination": "ga4", "seen": true}, {"browser": "firefox", "destination": "google_ads", "seen": true}, {"browser": "firefox", "destination": "meta", "seen": true},
          {"browser": "chrome_adblock", "destination": "ga4", "seen": true}, {"browser": "chrome_adblock", "destination": "google_ads", "seen": true}, {"browser": "chrome_adblock", "destination": "meta", "seen": true}
        ]
      },
      {
        "event": "funnel_step",
        "expected_parameters": ["funnel_name", "step_number", "step_name"],
        "example_payload": {"funnel_name": "checkout", "step_number": 2, "step_name": "shipping_info"},
        "results": [
          {"browser": "chrome", "destination": "ga4", "seen": true}, {"browser": "safari", "destination": "ga4", "seen": true}, {"browser": "firefox", "destination": "ga4", "seen": true}, {"browser": "chrome_adblock", "destination": "ga4", "seen": false}
        ]
      }
    ]
  }
}

{
  "site_domain": "example.com",
  "destinations": ["ga4", "google_ads", "meta"],
  "registry": {"file": "events.yml", "ci_validator": "validate-events.py", "enforced_in_ci": false},
  "consent": {
    "mode": "v2",
    "defaults_before_config": false,
    "signals": ["ad_storage", "analytics_storage"],
    "regional_defaults": [
      {"region": "default", "ad_storage": "granted", "analytics_storage": "granted", "ad_user_data": "granted", "ad_personalization": "granted"}
    ],
    "server_honours_consent": false
  },
  "server_side": {
    "enabled": true,
    "endpoint": "gtm-server.vendor.app",
    "cookies_http_only": false,
    "forwards": ["client_id"],
    "client_id_source": "uuid4 per hit",
    "fresh_ids_generated": true
  },
  "events": [
    {
      "name": "Order_Completed", "recommended": false, "monetary": true, "sent_from": ["browser", "server"],
      "parameters": [
        {"name": "value", "type": "number", "pii": false},
        {"name": "email", "type": "string", "max_string_length": 100, "pii": true}
      ],
      "conversion_role": {"ga4": "key_event", "google_ads": "primary", "meta": "custom"}
    },
    {
      "name": "checkout_step_completed_with_shipping_option_selected", "recommended": false, "monetary": false, "sent_from": ["browser"],
      "parameters": [],
      "conversion_role": {"ga4": "event"}
    }
  ],
  "qa": {
    "change_ref": "hotfix",
    "browsers": ["chrome"],
    "adblock_profile": false,
    "fixtures": [
      {
        "event": "Order_Completed",
        "expected_parameters": ["value"],
        "example_payload": {"value": 129.0, "email": "jane.doe@example.com", "phone": "+44 7700 900123"},
        "results": [{"browser": "chrome", "destination": "ga4", "seen": true}]
      }
    ]
  }
}
